/* Pure learning models shared by the resource reader and automated checks. */
function learningNormalize(value){return String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘]/g,"'")}
function decodeStudyCatalog(data){if(!data||data.version!==1||!Array.isArray(data.rows))throw Error('Catalogue invalide');return data.rows.map(row=>{const [id,title,s,c,u,t,l,d]=row;if(!/^(mdn-[a-f0-9]{16}|ka-[\w-]{11})$/.test(id)||typeof title!=='string')throw Error('Notice invalide');const f=id.startsWith('mdn-')?'article':'video';return {id,title,s,c:data.collections[c]||'',u:data.units[u]||'',t:data.topics[t]||'',l,d,p:f==='article'?'mdn':'khan',f,v:f==='video'?id.slice(3):''}})}
function learningTermMatches(text,term){const escaped=learningNormalize(term).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return new RegExp('(^|[^a-z0-9])'+escaped+'s?($|[^a-z0-9])').test(text)}
function matchLearningGuide(resource,guides){const title=learningNormalize(resource.title),unit=learningNormalize(resource.u);let best=null,high=0;for(const g of guides){if(!g.subjects.includes(resource.s))continue;let score=0,direct=false;for(const term of g.terms){if(learningTermMatches(title,term)){score+=6+Math.min(term.length/30,1);direct=true}else if(learningTermMatches(unit,term))score+=1}if(direct&&score>high){high=score;best=g}}return best}
function validStudyResourceId(id){return /^(mdn-[a-f0-9]{16}|ka-[\w-]{11})$/.test(String(id))}
function studyResourceUrls(id){if(!validStudyResourceId(id))throw Error('Identifiant de ressource invalide');return {metadata:'./library/resources/'+id+'.json',article:id.startsWith('mdn-')?'./library/articles/'+id+'.json':null}}
function studyQuestionResult(question,answer){if(!question||!Number.isInteger(answer)||answer<0||answer>=question.options.length)return null;return {correct:answer===question.answer,explanation:question.explanation}}
